PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS config (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resumes (id TEXT PRIMARY KEY, track TEXT NOT NULL, version INTEGER NOT NULL, name TEXT NOT NULL, sha256 TEXT NOT NULL, path TEXT NOT NULL, mime TEXT NOT NULL, created TEXT NOT NULL, is_default INTEGER NOT NULL DEFAULT 1, UNIQUE(track,version));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, canonical TEXT NOT NULL UNIQUE, source TEXT NOT NULL, source_id TEXT, data TEXT NOT NULL, first_seen TEXT NOT NULL, last_checked TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications (id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id), resume_id TEXT REFERENCES resumes(id), status TEXT NOT NULL, data TEXT NOT NULL, created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, app_id TEXT, kind TEXT NOT NULL, message TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, kind TEXT NOT NULL, company TEXT NOT NULL, board TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, health TEXT NOT NULL DEFAULT 'Never run', last_run TEXT, error TEXT, count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS queue (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', created TEXT NOT NULL, started TEXT, finished TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES applications(id), name TEXT NOT NULL, path TEXT NOT NULL, mime TEXT NOT NULL, sha256 TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS queue_status ON queue(status,created);
CREATE INDEX IF NOT EXISTS event_app ON events(app_id,id);
